class AgentDiagram(Flowable):
    def __init__(self): super().__init__(); self.width=250; self.height=111
    def draw(self):
        c=self.canv
        boxes=[(0,70,54,30,"User"),(68,70,76,30,"Web / CLI"),(158,70,83,30,"Agent"),
               (10,8,78,30,"Recipe APIs"),(100,8,68,30,"Planner"),(182,8,58,30,"Memory")]
        for x,y,w,h,label in boxes:
            c.setFillColor(LIGHT); c.setStrokeColor(BLACK); c.roundRect(x,y,w,h,5,fill=1,stroke=1)
            c.setFillColor(BLACK); c.setFont("TimesNewRoman",7.5); c.drawCentredString(x+w/2,y+11,label)
        c.setStrokeColor(BLACK); c.setLineWidth(1)
        for x1,y1,x2,y2 in [(54,85,68,85),(144,85,158,85),(190,70,48,38),(196,70,134,38),(212,70,211,38)]:
            c.line(x1,y1,x2,y2); c.line(x2,y2,x2-3,y2+3); c.line(x2,y2,x2-3,y2-3)

class EvalChart(Flowable):
    def __init__(self): super().__init__(); self.width=250; self.height=100
    def draw(self):
        c=self.canv; c.setFont("TimesNewRoman",9); c.setFillColor(colors.black)
        c.drawString(0,88,"Existing automated regression suite (n=25)")
        c.setFillColor(colors.HexColor("#777777")); c.rect(0,52,210,18,fill=1,stroke=0)
        c.setFillColor(colors.black); c.drawString(4,58,"Passed: 25 (100%)")
        c.setFillColor(colors.HexColor("#B64B4B")); c.rect(0,24,0,18,fill=1,stroke=0)
        c.setFillColor(colors.black); c.drawString(0,30,"Failed: 0")
        c.setFont("TimesNewRoman-Italic",8); c.setFillColor(colors.black)
        c.drawString(0,6,"Functional checks; not a measure of recommendation quality or user satisfaction.")

styles=getSampleStyleSheet()
