class Paper(BaseDocTemplate):
    def __init__(self,filename):
        super().__init__(filename,pagesize=letter,leftMargin=.72*inch,rightMargin=.72*inch,topMargin=.62*inch,bottomMargin=.55*inch)
        w=(letter[0]-1.44*inch-.22*inch)/2; h=letter[1]-1.62*inch
        self.addPageTemplates([PageTemplate(id="IEEE",frames=[Frame(.72*inch,.55*inch,w,h,id="L",leftPadding=0,rightPadding=5,topPadding=0,bottomPadding=0),Frame(.72*inch+w+.22*inch,.55*inch,w,h,id="R",leftPadding=5,rightPadding=0,topPadding=0,bottomPadding=0)],onPage=self.header)])
    def header(self,c,doc):
        if doc.page == 1:
            c.saveState();c.setFillColor(BLACK);c.setFont("TimesNewRoman-Bold",16)
            c.drawCentredString(letter[0]/2,10.58*inch,"PantryPal: A Constraint-Aware Recipe Planning Agent")
            c.setFillColor(colors.black);c.setFont("TimesNewRoman",10)
            c.drawCentredString(letter[0]/2,10.31*inch,"Student Project Paper  |  Intelligent Agents")
            c.restoreState()
    def afterPage(self):
        c=self.canv;c.saveState();c.setFont("TimesNewRoman",8);c.setFillColor(colors.black);c.drawCentredString(letter[0]/2,.28*inch,str(self.page));c.restoreState()

def P(text,style=body): return Paragraph(text,style)
story=[]
story += [P("<b>Abstract—</b> PantryPal is a hybrid recipe discovery and meal-planning agent that helps users select meals under dietary, allergy, pantry, time, budget, and serving constraints. Its local planner evaluates a curated catalog with a bounded beam search, while its online path retrieves recipes from TheMealDB, filters and ranks candidates, combines recipes into plans, and aggregates missing ingredients. Persistent preference feedback adjusts later rankings. A browser interface adds searchable recipes, surprise selection, saved recipes, a shopping list, export, and estimated nutrition. We describe the agent using PEAS and environment properties, explain its decision pipeline, and evaluate its existing regression suite. All 25 tests passed; this establishes tested functional behavior, not recommendation accuracy or user benefit. We discuss the limitations of a small built-in catalog, incomplete external ingredient data, heuristic nutrition estimates, and non-learning ranking rules.",abstract),Spacer(1,3),P("<b>Index Terms—</b> intelligent agents, meal planning, constraint satisfaction, recipe recommendation, beam search",small),P("I. INTRODUCTION",head)]
story += [P("Meal planning requires balancing several goals at once: use ingredients already available, satisfy dietary and allergy preferences, stay within time and cost limits, and produce a usable shopping list. A search box alone returns recipes but does not resolve these trade-offs across multiple meals. PantryPal treats meal selection as a goal-directed decision problem: it collects a user request, rejects infeasible recipes, ranks feasible combinations, and presents a plan with groceries and explanations.")]
story += [P("The system is a hybrid agent. In offline mode, a deterministic planner selects from a bundled recipe catalog. In online mode, it obtains recipe candidates from TheMealDB and applies local matching, preference screening, scoring, and plan assembly. The project makes three practical contributions: (1) explicit constraint handling with pantry-aware scoring; (2) multi-recipe selection and grocery aggregation; and (3) a working browser interface that connects the decision logic to recipe discovery and feedback.")]
story += [P("II. PROBLEM AND AGENT DESIGN",head),P("A. PEAS Description",sub)]
peas=[[P("Element",small),P("PantryPal specification",small)],[P("Performance",small),P("Feasible meals; pantry use; protein; time and cost limits; shared ingredients; usable grocery list; user feedback",small)],[P("Environment",small),P("Single user, local computer/browser, curated recipe data and optional external TheMealDB service; partially observable pantry and recipe details",small)],[P("Actuators",small),P("Display plans, recipe details, labels, substitutions, grocery list, saved recipes, exports, and feedback prompts",small)],[P("Sensors",small),P("User-entered ingredients/quantities, servings, diet, allergies, time, budget, moods, and like/dislike feedback; API meal records",small)]]
t=Table(peas,colWidths=[.78*inch,2.56*inch],repeatRows=1);t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#D9D9D9")),("TEXTCOLOR",(0,0),(-1,0),colors.black),("GRID",(0,0),(-1,-1),.35,colors.black),("VALIGN",(0,0),(-1,-1),"TOP"),("BACKGROUND",(0,1),(-1,-1),colors.white),("LEFTPADDING",(0,0),(-1,-1),4),("RIGHTPADDING",(0,0),(-1,-1),4),("TOPPADDING",(0,0),(-1,-1),4),("BOTTOMPADDING",(0,0),(-1,-1),4)]));story += [t,P("TABLE I. PEAS model of PantryPal.",caption)]
story += [P("B. Environment Characterization",sub),P("The task is episodic at the interface level but sequential across a session because saved feedback influences later rankings. The environment is partially observable: the agent sees only entered pantry quantities and ingredients exposed by the recipe source. It is mostly deterministic locally; online results and network availability are nondeterministic. The agent is single-user and software-mediated. The planner is model-based with an explicit state of remaining pantry stock and goal-based because it seeks a set of meals satisfying hard constraints while optimizing a score [1].")]
story += [P("C. Agent Architecture",sub),AgentDiagram(),P("Fig. 1. User request flows through the interface to local filtering, planning, and preference memory; online candidates come from TheMealDB.",caption)]
story += [P("III. METHODOLOGY",head),P("A. State, Constraints, and Candidate Preparation",sub),P("The request contains meal count, servings, pantry inventory, diet, allergies, time, cost, protein, and optional cuisine or mood. Built-in recipes carry ingredients, quantities, estimated cost, time, protein, and tags. Online records are parsed into normalized ingredient names, measures, instructions, cuisine, category, and source URL. Aliases and typo matching reduce spelling variation. Diet and allergen rules are applied before ranking; infeasible recipes are removed rather than given a small score penalty.")]
story += [P("B. Built-In Planning",sub),P("The local planner builds plans incrementally. A state stores its accumulated score, selected recipes, cost, and remaining pantry stock. At each meal position it expands feasible recipe choices, computes their score, sorts expansions, and retains at most 300 states (beam width). Hard checks enforce budget, time, diet, allergy, serving, and protein constraints. The score rewards pantry utilization and protein, penalizes time and cost, and adjusts for user likes or dislikes. The best surviving state becomes the plan. Beam search bounds computation but does not guarantee the global optimum.")]
story += [P("C. Online Planning and Grocery Actions",sub),P("Online retrieval uses TheMealDB V1 endpoints for name search, ingredient/cuisine filters, details, and random selection [2]. Candidate recipes receive preference screening and a local rank informed by query relevance, pantry overlap, and feedback. The online planner enumerates combinations of the requested size and rewards candidate rank, shared ingredients, and pantry coverage. It aggregates recipe quantities, subtracts pantry stock, and formats package-size suggestions. Related variants use ingredient-set overlap plus shared cuisine/category; substitutions are offered only if the alternative appears in the pantry and passes the preference screen. The browser stores saved recipes and shopping-list state locally.")]
story += [P("D. Feedback and Nutrition",sub),P("Like/dislike responses are stored as local recipe identifiers and adjust future rankings. This is preference adaptation, not model training: it uses a simple memory-based score adjustment. Online nutrition is not supplied by the API, so PantryPal estimates calories and protein from listed quantities and coarse ingredient profiles. These whole-recipe estimates are approximate and may be inaccurate when measures or ingredient classifications are incomplete.")]
story += [P("E. User-Facing Features and Interaction",sub),P("The web application presents the online discovery workflow above the built-in planner. Users can search by dish, main ingredient, cuisine, or food mood; the Surprise Me action selects a random recipe from the matching candidate set, or requests a random recipe when no search fields are supplied. The homepage carousel cycles through cached TheMealDB picks and displays three cards at a time. Selecting a card opens an in-page recipe panel rather than a separate window. Search results expose the recipe image, name, source metadata, ingredient list, and instructions. Labels are inferred from category, area, and text rules so users can scan broad cuisine and food-type cues.")]
story += [P("The planner form accepts several tokenized dish or ingredient terms, pantry items with amounts and units, diet, allergies, meal count, moods, and a leftovers option. The input chips support removal and ingredient auto-completion. A results panel presents selected meals and the combined shopping list. Browser features include saving recipes to local storage, checking off and editing shopping-list quantities, exporting plan data, searching live results, and viewing a recipe without navigating away. These functions reduce the steps between recommendation and cooking, while the agent itself remains the decision-making component that evaluates candidate meals.")]
story += [P("F. Agent Type and Rational Action",sub),P("PantryPal is best described as a model-based, goal-based, utility-scored software agent with a simple feedback memory. Its internal model includes normalized ingredient quantities and the residual pantry after a recipe is selected. Goals are expressed through feasibility conditions: a plan must not exceed configured limits and must respect selected exclusions based on available data. Among feasible plans, the scoring function represents trade-offs. The system is not fully rational in the formal sense of maximizing expected performance under a complete model, because recipe data, quantities, nutrition, and user preferences are uncertain or missing. Its practical policy is a bounded approximation intended to return useful plans quickly and explainably.")]
story += [P("The distinction between hard constraints and soft preferences is central. A chosen diet or allergy exclusion should not be traded against a small score bonus. It is therefore applied during feasibility screening. Pantry use, protein, time, cost, candidate relevance, and shared ingredients are graded objectives. User feedback influences ranking but does not override explicit constraints. This ordering gives the planner a predictable response: first remove unacceptable options, then compare the remaining alternatives.")]
story += [P("G. Search Objective",sub),P("For an offline recipe r, the implementation uses a weighted score with a positive term for pantry coverage and protein, and negative terms for preparation time and estimated cost; saved like/dislike signals add or subtract fixed preference values. Multi-meal search adds a small bonus when recipes share ingredients, encouraging grocery-list reuse. Online meal combinations similarly combine each meal's candidate rank, overlap across selected meals, and the fraction of requested ingredients already in stock. Quantities are aggregated by canonical ingredient and unit before available stock is subtracted. This scoring design is transparent and deterministic, but fixed weights encode assumptions rather than learned user utility.")]
story += [P("A plan can fail to exist when hard limits conflict or when the candidate pool is too small. The built-in planner reports infeasibility rather than silently relaxing a constraint. Online search can also return fewer distinct meals than requested because TheMealDB retrieval yields a finite set. The implementation's online plan builder selects combinations from candidates it receives; it cannot establish that no suitable recipe exists elsewhere in the database. These are important boundaries on the agent's claims and on the completeness of its search.")]
story += [P("H. Worked Decision Trace",sub),P("Consider a request for two dinners, vegetarian, under a selected time limit, with rice and chickpeas already in the pantry. Candidate generation first retrieves recipes whose names, ingredients, or cuisine metadata match the query. The preference screen removes recipes with listed ingredients that conflict with vegetarian rules. Remaining candidates are checked against per-meal and plan-level limits. For each feasible candidate, the agent compares requested servings with recipe quantities, estimates pantry coverage using normalized ingredient and unit pairs, and calculates a score. The beam search extends partial plans until it reaches the required meal count, keeping at most 300 promising states at each depth. If two candidate meals both use rice, the planner can reward that shared ingredient and the final shopping aggregation counts rice once with combined quantity. It then subtracts the user's available rice stock and emits only the deficit. This trace illustrates observable steps; the example is explanatory and is not a measured result.")]
story += [P("I. Data Handling and Failure Behavior",sub),P("The software separates editable vocabularies and rules from the main agent code. JSON data files hold ingredient aliases, cuisine and mood terms, dietary screening rules, package sizes, unit conversions, and substitution mappings. The recipe API module owns HTTP requests, parsing, ingredient normalization, typo suggestions, and saved online feedback. Planner logic is separated from both the command-line and browser interfaces. This organization lets the same recipe-ranking and planning routines serve different front ends and makes rule changes less likely to require changing the interface.")]
story += [P("When a typo has one strong candidate, search can use that normalized ingredient; when several terms are similarly plausible, the command-line workflow asks the user rather than silently choosing. API errors are converted to a domain error and shown to the user so the offline planner remains accessible. A missing optional thumbnail is rendered with a placeholder. The browser persists saved recipes and shopping progress in local storage, while recommendation feedback is held in a local JSON file. These persistence mechanisms are not synchronized across devices and do not constitute a shared user profile.")]
story += [P("J. Interpretability and User Control",sub),P("Several choices make the agent's behavior inspectable. Diet and allergy conditions are visible inputs and are treated as filters; labels describe inferred recipe attributes; recipe cards link to source details; and the shopping list exposes the ingredient deficits behind a plan. Users can edit quantities, remove pantry tokens, choose a different mood or query, and save or reject recipes. The system does not expose a numerical explanation of every score term in the interface, so its ranking is only partially interpretable. A future explanation panel could list matched constraints, pantry items used, missing ingredients, and the principal score contributions without overwhelming the cooking workflow.")]
story += [P("IV. RESULTS AND EVALUATION",head),P("A. Functional Test Results",sub),P("We ran the repository's 25-test standard-library regression suite. All 25 passed. Tests cover ingredient aliases and typos, unit conversion, diet/allergy screening, built-in feasibility, budget and leftovers, shared-ingredient ranking, substitutions, labels and variants, saved feedback, API error handling, and mocked online workflows. Independent checks compiled the Python modules and exercised the local browser homepage, random Surprise Me, filtered Surprise Me, and nutrition detail rendering. A live TheMealDB tomato search returned 11 recipes in this run. These checks validate functionality under the tested conditions; they do not establish ranking quality, nutritional accuracy, or user satisfaction.")]
story += [EvalChart(),P("Fig. 2. Existing regression suite outcome (25 tests).",caption),P("B. Interpretation",sub),P("The results show that key planner and online-search paths behave as expected for the covered cases, including graceful network-error handling and preference-aware meal selection. The local planner can operate without an internet connection. Online search and homepage picks require connectivity and depend on TheMealDB response quality and availability. The free API documentation identifies a test key and notes service limits; deployments should follow the provider's current terms [2].")]
story += [P("C. Limitations",sub),P("The built-in catalog is intentionally small, so offline variety is limited. Online ingredient lists may omit details, and synonym or typo matching can produce uncertain interpretations. Food-label inference is rule-based; combined mood terms can narrow results substantially. Online plan combination is exhaustive over the fetched candidate set, not over the full recipe database. Nutrition calculations are heuristic, and dietary/allergen screening cannot guarantee safety. No user study, blind comparison, response-time benchmark, or nutrition validation was conducted. The 25 passing tests measure software behavior, not agent effectiveness in real meal planning.")]
story += [P("D. Validity of the Evaluation",sub),P("The test suite provides repeatable evidence for the covered software paths. Most external-service behavior is tested with mocked responses so tests remain deterministic and do not depend on network conditions. The separate live search verifies that the configured service was reachable at the time of this evaluation; it is a snapshot rather than a service-level guarantee. The test sample is the project’s existing suite, not an independently designed benchmark. Pass rate should therefore be interpreted as regression status only. It does not measure precision, recall, ranking gain, calories error, grocery savings, or task completion time.")]
story += [P("A stronger evaluation would define a representative set of user requests with known constraints and judged acceptable recipes. It would compare PantryPal’s top-ranked plans against a popularity baseline and a pantry-only baseline, report constraint-violation rates, and measure ingredient utilization, grocery-list size, plan diversity, and user-rated relevance. Nutrition estimates would require comparison with a validated nutrient database and standardized serving sizes. Testing across several network failure conditions and malformed API results would characterize robustness. Those evaluations are future work; no such results are claimed here.")]
story += [P("E. Evaluation Plan for a Follow-Up Study",sub),P("A practical next study could recruit users who regularly plan meals and present each participant with several realistic pantry scenarios. For each scenario, the participant would enter pantry amounts, servings, diet, allergies, time, and mood, then review PantryPal's top plan and a baseline plan. A within-subject design would reduce differences in cooking experience between groups. The study should record whether the plan satisfies each explicit constraint, whether users would cook the selected meals, how many recommendations they reject, and how much time the task takes. Short interviews could identify unclear labels, confusing substitutions, or grocery-list errors.")]
story += [P("Before such a study, the team would need a labeled evaluation set and a reproducible protocol. Recipe relevance judgments should distinguish hard failures, such as an allergy conflict, from softer disagreements about taste. Candidate sources and retrieval dates should be recorded because an online recipe database can change. The baseline should use the same candidate set and hard-constraint filters; otherwise a comparison could conflate retrieval coverage with planning quality. Statistical summaries should report sample sizes and uncertainty, and any nutrition comparison should state serving assumptions. This plan is proposed work, not evidence collected for the present paper.")]
story += [P("F. Improvement Priorities",sub),P("The next engineering step is to make uncertainty more visible. PantryPal could identify ingredients whose parsed quantities were absent or interpreted through a generic unit, show a confidence note for inferred labels, and distinguish data supplied by TheMealDB from values estimated locally. For nutrition, replacing the heuristic profiles with a maintained nutrient database would require mapping ingredient names and recipe quantities to canonical food entries, accounting for edible portions, and normalizing results by a declared serving count. Until that mapping is validated, estimates should remain clearly labeled as rough.")]
story += [P("Search quality could improve by measuring retrieval coverage and diversifying the candidate pool before plan scoring. If a search returns many near-duplicate meals, the planner may miss distinct cuisines or preparation styles even when its combination algorithm is correct. A diversity term or cuisine cap could address this, but it should be tested against user preferences rather than assumed to help. Similarly, aliases and typo matching could record the chosen correction and allow quick reversal, especially when a misspelling maps to different ingredients. These proposals modify ranking and interaction behavior and should be evaluated before being described as improvements.")]
story += [P("The current architecture has clear expansion points: recipe-source adapters can isolate service-specific fields; normalized recipe objects can support multiple sources; constraint checks can be shared by the local and online planners; and a planner interface can expose alternatives for comparison. Such changes would make it easier to add calendar planning, pantry expiry dates, or user-defined objectives while keeping the core policy auditable. They would also add state-management and data-quality requirements. This project therefore favors incremental features that preserve explicit constraints and report what evidence each recommendation used.")]
story += [P("V. CONCLUSION",head),P("PantryPal demonstrates a practical goal-based intelligent agent that turns pantry and preference inputs into feasible meal plans and consolidated shopping actions. Its local bounded search and online retrieval path share constraint checks and preference-aware ranking while supporting a richer web workflow. The verified test suite and live smoke checks support the implementation's functional completeness for the tested paths. Future work should evaluate recommendation relevance with users, expand the offline catalog, add validated nutrition data, improve uncertainty reporting, and measure plan quality against a transparent baseline.")]
story += [P("REFERENCES",head),P("[1] S. Russell and P. Norvig, <i>Artificial Intelligence: A Modern Approach</i>, 4th ed. Hoboken, NJ, USA: Pearson, 2021.",small),P("[2] TheMealDB, “API Guide,” accessed Nov. 5, 2026. [Online]. Available: https://www.themealdb.com/docs_api_guide.php",small),P("[3] IEEE Author Center, “Structure Your Paper,” accessed Nov. 5, 2026. [Online]. Available: https://conferences.ieeeauthorcenter.ieee.org/write-your-paper/structure-your-paper/",small),P("[4] PantryPal source code and regression suite, project repository, commit 19e8af2, Nov. 2026.",small)]

Paper(OUT).build(story)
print(OUT)
